export default class Header {
  constructor(element) {
    this.element = element;
    this.options = {
      treshold: 0.1,
    };

    this.scrollPosition = 0;
    this.lastScrollPosition = 0;

    this.html = document.documentElement;

    this.init();
    this.initNavMobile();
  }

  init() {
    // console.log('Nouvelle instance de la composante -> Header');
    this.setOptions();

    window.addEventListener('scroll', this.onScroll.bind(this));
  }

  setOptions() {
    //Vérifier les différents attributs data sur la composante
    if ('treshold' in this.element.dataset) {
      // console.log(this.element.dataset.treshold);

      this.options.treshold = this.element.dataset.treshold;
    }

    if ('alwaysShow' in this.element.dataset) {
      // console.log(this.element.dataset);
      this.options.treshold = Infinity;
    }
  }

  onScroll() {
    // console.log('scroll')
    this.lastScrollPosition = this.scrollPosition;
    this.scrollPosition = document.scrollingElement.scrollTop;

    // console.log(this.lastScrollPosition, this.scrollPosition)

    this.setHeaderState();
    this.setDirections();
  }

  setHeaderState() {
    if (
      this.scrollPosition >
      document.scrollingElement.scrollHeight * this.options.treshold
    ) {
      this.html.classList.add('header-is-hidden');
    } else {
      this.html.classList.remove('header-is-hidden');
    }
  }

  setDirections() {
    if (this.scrollPosition >= this.lastScrollPosition) {
      //scroll vers le bas
      this.html.classList.remove('is-scrolling-up');
      this.html.classList.add('is-scrolling-down');
    } else {
      //scroll vers le haut
      this.html.classList.remove('is-scrolling-down');
      this.html.classList.add('is-scrolling-up');
    }
  }

  initNavMobile() {
    // const toggleElements = this.element.querySelectorAll('.js-toggle');
    const toggleElements = document.querySelectorAll('.js-toggle');
    // console.log(toggle);

    for (let i = 0; i < toggleElements.length; i++) {
      const toggleElement = toggleElements[i];
      toggleElement.addEventListener('click', this.onToggleNav.bind(this));
    }
  }

  onToggleNav() {
    this.html.classList.toggle('nav-is-active');
  }
}
