import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger.js';
import { ScrollSmoother } from 'gsap/ScrollSmoother.js';

export default class Scrooler {
  constructor(element) {
    // console.log('composante Scroller est instancié');
    gsap.registerPlugin(ScrollTrigger, ScrollSmoother);
    this.options = {
      hasSkew: false,
      hasPinItems: false,
    };

    this.element = element;
    this.setOptions();
    this.init();
  }

  init() {
    const scroller = ScrollSmoother.create({
      smooth: 2,
      effects: true,
      smoothTouch: 0.1,
      onUpdate: this.onUpdateScroll.bind(this),
      onStop: this.onStopScroll.bind(this),
      ease: 'expo.out',
    });
  }

  //SCROLL CONTROLS
  onUpdateScroll(self) {
    this.updateSkew(self);
  }

  onStopScroll(self) {
    this.stopSkew(self);
  }

  //SKEW CONTROLS
  //voir scaleSetter
  initSkew() {
    this.skewSetter = gsap.quickTo('img', 'skewX');
  }

  updateSkew(self) {
    const velocity = self.getVelocity();
    const force = 0;
    let skew = gsap.utils.mapRange(-1000, 1000, -force, force, velocity);
    skew = gsap.utils.clamp(-force, force, skew);

    this.skewSetter(skew);
  }

  stopSkew() {
    this.skewSetter(0);
  }

  //PIN CONTROLS
  initPins() {
    // console.log('pins');
    const pinnedItems = this.element.querySelectorAll('.js-pinned');
    for (let i = 0; i < pinnedItems.length; i++) {
      const pinnedItem = pinnedItems[i];
      ScrollTrigger.create({
        pin: pinnedItem,
        trigger: pinnedItem.parentElement,
        start: 'center center',
        end: '80% center',
        // markers: true, // DEBUG MODE: permet de vérifier où débute/fini le pin
      });
    }
  }

  //HORI SCROLL CONTROLS
  initHoriz() {
    const sectionHoriz = this.element.querySelector('.js-horiz');

    //QuerySelectorAll
    //Boucler dans les sections
    //createHoriz

    // console.log(sectionHorizontale);
    const panels = sectionHoriz.querySelectorAll('.js-panel');
    const nbPanels = panels.length - 1;
    const buffer = 200;

    gsap.to(panels, {
      xPercent: -100 * nbPanels,
      ease: 'none',
      scrollTrigger: {
        pin: true,
        trigger: sectionHoriz,
        scrub: 1, //lie positionnement du scroll à la section
        snap: 1 / nbPanels,
        end: () => '+=' + (sectionHoriz.offsetWidth + buffer),
      },
    });
  }

  //OPTIONS CONTROLS
  setOptions() {
    if ('skew' in this.element.dataset) {
      this.options.hasSkew = true;
      this.initSkew();
    }
    if ('pinItems' in this.element.dataset) {
      this.options.hasPinItems = true;
      this.initPins();
    }

    if (this.element.querySelector('.js-horiz')) {
      this.initHoriz();
    }
  }
  //data Options
  // data-speed='0.x' change la vitesse de défilement
  // data-lag='0.x' change le lag lors du défilement
}
